export const script = "\n    function setMarketplaceMode(mode) {\n      const btnMulti = document.getElementById('btnMultiVendor');\n      const btnSingle = document.getElementById('btnSingleOwner');\n      const descriptor = document.getElementById('modeDescriptor');\n      const creatorBadges = document.querySelectorAll('.creator-badge');\n      const vendorBlocks = document.querySelectorAll('.vendor-only-block');\n      const singleBlocks = document.querySelectorAll('.single-only-block');\n      const shellSellerLink = document.querySelector('[data-path=\"seller-onboarding\"]');\n      const shellCreatorsLink = document.querySelector('[data-path=\"featured-creators\"]');\n\n      if (mode === 'single') {\n        // Toggle Buttons\n        btnMulti.classList.remove('bg-surface', 'text-on-surface', 'shadow-sm');\n        btnMulti.classList.add('text-text-muted');\n        btnSingle.classList.add('bg-surface', 'text-on-surface', 'shadow-sm');\n        btnSingle.classList.remove('text-text-muted');\n\n        descriptor.textContent = \"Boutique flagship active: Creator tags, 'Become a Seller' CTAs, and vendor directories are suppressed.\";\n\n        // Suppress Multi-Vendor Elements\n        creatorBadges.forEach(badge => badge.classList.add('hidden'));\n        vendorBlocks.forEach(block => block.classList.add('hidden'));\n        singleBlocks.forEach(block => block.classList.remove('hidden'));\n\n        if (shellSellerLink) shellSellerLink.classList.add('hidden');\n        if (shellCreatorsLink) shellCreatorsLink.classList.add('hidden');\n      } else {\n        // Multi-Vendor mode active\n        btnSingle.classList.remove('bg-surface', 'text-on-surface', 'shadow-sm');\n        btnSingle.classList.add('text-text-muted');\n        btnMulti.classList.add('bg-surface', 'text-on-surface', 'shadow-sm');\n        btnMulti.classList.remove('text-text-muted');\n\n        descriptor.textContent = \"Platform runs with creator attribution, seller hubs, commission splits, and open vendor onboarding.\";\n\n        // Show Multi-Vendor Elements\n        creatorBadges.forEach(badge => badge.classList.remove('hidden'));\n        vendorBlocks.forEach(block => block.classList.remove('hidden'));\n        singleBlocks.forEach(block => block.classList.add('hidden'));\n\n        if (shellSellerLink) shellSellerLink.classList.remove('hidden');\n        if (shellCreatorsLink) shellCreatorsLink.classList.remove('hidden');\n      }\n    }\n  ";
